1	#!/usr/bin/env node
2	import { spawnSync, spawn } from 'child_process';
3	import { existsSync, readFileSync, mkdirSync, appendFileSync, writeFileSync } from 'fs';
4	import { join, dirname, resolve } from 'path';
5	import { homedir } from 'os';
6	import { fileURLToPath } from 'url';
7	
8	const IS_WINDOWS = process.platform === 'win32';
9	
10	const __bun_runner_dirname = dirname(fileURLToPath(import.meta.url));
11	const RESOLVED_PLUGIN_ROOT = process.env.CLAUDE_PLUGIN_ROOT || resolve(__bun_runner_dirname, '..');
12	
13	function fixBrokenScriptPath(argPath) {
14	  if (argPath.startsWith('/scripts/') && !existsSync(argPath)) {
15	    const fixedPath = join(RESOLVED_PLUGIN_ROOT, argPath);
16	    if (existsSync(fixedPath)) {
17	      return fixedPath;
18	    }
19	  }
20	  return argPath;
21	}
22	
23	function findBun() {
24	  const pathCheck = IS_WINDOWS
25	    ? spawnSync('where bun', {
26	        encoding: 'utf-8',
27	        stdio: ['pipe', 'pipe', 'pipe'],
28	        shell: true
29	      })
30	    : spawnSync('which', ['bun'], {
31	        encoding: 'utf-8',
32	        stdio: ['pipe', 'pipe', 'pipe']
33	      });
34	
35	  if (pathCheck.status === 0 && pathCheck.stdout.trim()) {
36	    if (IS_WINDOWS) {
37	      const bunCmdPath = pathCheck.stdout.split('\n').find(line => line.trim().endsWith('bun.cmd'));
38	      if (bunCmdPath) {
39	        return bunCmdPath.trim();
40	      }
41	    }
42	    return 'bun'; 
43	  }
44	
45	  const bunPaths = IS_WINDOWS
46	    ? [join(homedir(), '.bun', 'bin', 'bun.exe')]
47	    : [
48	        join(homedir(), '.bun', 'bin', 'bun'),
49	        '/usr/local/bin/bun',
50	        '/opt/homebrew/bin/bun',
51	        '/home/linuxbrew/.linuxbrew/bin/bun'
52	      ];
53	
54	  for (const bunPath of bunPaths) {
55	    if (existsSync(bunPath)) {
56	      return bunPath;
57	    }
58	  }
59	
60	  return null;
61	}
62	
63	function isPluginDisabledInClaudeSettings() {
64	  try {
65	    const configDir = process.env.CLAUDE_CONFIG_DIR || join(homedir(), '.claude');
66	    const settingsPath = join(configDir, 'settings.json');
67	    if (!existsSync(settingsPath)) return false;
68	    const settings = JSON.parse(readFileSync(settingsPath, 'utf-8'));
69	    return settings?.enabledPlugins?.['claude-mem@thedotmack'] === false;
70	  } catch {
71	    return false;
72	  }
73	}
74	
75	if (isPluginDisabledInClaudeSettings()) {
76	  process.exit(0);
77	}
78	
79	const args = process.argv.slice(2);
80	
81	if (args.length === 0) {
82	  console.error('Usage: node bun-runner.js <script> [args...]');
83	  process.exit(1);
84	}
85	
86	args[0] = fixBrokenScriptPath(args[0]);
87	
88	const bunPath = findBun();
89	
90	if (!bunPath) {
91	  console.error('Error: Bun not found. Please install Bun: https://bun.sh');
92	  console.error('After installation, restart your terminal.');
93	  process.exit(1);
94	}
95	
96	function collectStdin() {
97	  return new Promise((resolve) => {
98	    if (process.stdin.isTTY) {
99	      resolve(null);
100	      return;
101	    }
102	
103	    const chunks = [];
104	    process.stdin.on('data', (chunk) => chunks.push(chunk));
105	    process.stdin.on('end', () => {
106	      resolve(chunks.length > 0 ? Buffer.concat(chunks) : null);
107	    });
108	    process.stdin.on('error', () => {
109	      resolve(null);
110	    });
111	
112	    setTimeout(() => {
113	      process.stdin.removeAllListeners();
114	      process.stdin.pause();
115	      resolve(chunks.length > 0 ? Buffer.concat(chunks) : null);
116	    }, 5000);
117	  });
118	}
119	
120	const stdinData = await collectStdin();
121	
122	const spawnOptions = {
123	  stdio: ['pipe', 'inherit', 'inherit'],
124	  windowsHide: true,
125	  env: process.env
126	};
127	
128	let spawnCmd = bunPath;
129	let spawnArgs = args;
130	
131	if (IS_WINDOWS) {
132	  const quote = (s) => `"${String(s).replace(/"/g, '\\"')}"`;
133	  spawnOptions.shell = true;
134	  spawnCmd = [bunPath, ...args].map(quote).join(' ');
135	  spawnArgs = [];
136	}
137	
138	const child = spawn(spawnCmd, spawnArgs, spawnOptions);
139	
140	if (child.stdin) {
141	  if (stdinData && stdinData.length > 0) {
142	    child.stdin.write(stdinData);
143	    child.stdin.end();
144	  } else {
145	    // Issue #2188: empty/missing stdin previously masked by `|| '{}'` fallback,
146	    // which silently hid WSL bash failures (e.g. hooks invoked under a broken
147	    // shell that never piped a payload). Surface the failure mode instead.
148	    const dataDir = process.env.CLAUDE_MEM_DATA_DIR || join(homedir(), '.claude-mem');
149	    const payloadType = stdinData === null
150	      ? 'null (no data event or stream error)'
151	      : stdinData === undefined
152	        ? 'undefined'
153	        : Buffer.isBuffer(stdinData) && stdinData.length === 0
154	          ? 'empty Buffer (zero bytes received)'
155	          : `unexpected (${typeof stdinData})`;
156	    const payloadByteLength = (stdinData && typeof stdinData.length === 'number')
157	      ? stdinData.length
158	      : 0;
159	    const diagnostic = [
160	      `[bun-runner] empty stdin payload received — issue #2188`,
161	      `  script: ${args[0]}`,
162	      `  payload byte length: ${payloadByteLength}`,
163	      `  payload type: ${payloadType}`,
164	      `  platform: ${process.platform}`,
165	      `  shell: ${process.env.SHELL || 'n/a'}`,
166	      `  stdin TTY: ${process.stdin.isTTY === true ? 'true' : process.stdin.isTTY === false ? 'false' : 'undefined'}`,
167	      `  timestamp: ${new Date().toISOString()}`,
168	      `  CLAUDE_PLUGIN_ROOT: ${RESOLVED_PLUGIN_ROOT}`,
169	    ].join('\n');
170	
171	    // Write to stderr so Claude Code surfaces the diagnostic.
172	    console.error(diagnostic);
173	
174	    // Persist diagnostic to the runner-errors log and drop a CAPTURE_BROKEN marker
175	    // file so the next session-start hint can surface the failure. We exit 0 to
176	    // honor the project's exit-code strategy (worker/hook errors exit 0 to
177	    // prevent Windows Terminal tab pileup) — the marker file is the durable
178	    // signal that something is wrong, not the exit code.
179	    try {
180	      const logsDir = join(dataDir, 'logs');
181	      mkdirSync(logsDir, { recursive: true });
182	      appendFileSync(join(logsDir, 'runner-errors.log'), diagnostic + '\n\n');
183	      mkdirSync(dataDir, { recursive: true });
184	      writeFileSync(join(dataDir, 'CAPTURE_BROKEN'), diagnostic + '\n');
185	    } catch (writeErr) {
186	      console.error(`[bun-runner] failed to persist diagnostic: ${writeErr && writeErr.message ? writeErr.message : writeErr}`);
187	    }
188	
189	    try { child.stdin.end(); } catch {}
190	    try { child.kill(); } catch {}
191	    process.exit(0);
192	  }
193	}
194	
195	child.on('error', (err) => {
196	  console.error(`Failed to start Bun: ${err.message}`);
197	  process.exit(1);
198	});
199	
200	child.on('close', (code, signal) => {
201	  if ((signal || code > 128) && args.includes('start')) {
202	    process.exit(0);
203	  }
204	  process.exit(code || 0);
205	});
